import { Aperture, Blocks, Bot, ChartNoAxesColumn, CircleUserRound, Database, Gauge, Settings2, Sparkles } from '../icons'
import { NavLink, Outlet } from 'react-router-dom'
import { useMemory } from '../state/MemoryContext'
import styles from './AppShell.module.css'

const nav = [
  { to: '/home', label: 'Home', sub: '나의 기억', icon: Aperture },
  { to: '/changes', label: 'Changes', sub: '이번 주 변화', icon: Sparkles, badge: '2' },
  { to: '/memory/half-life', label: 'Memory', sub: '기억 탐색', icon: ChartNoAxesColumn },
  { to: '/chat', label: 'Chat', sub: '대화 수정', icon: Bot },
  { to: '/access', label: 'Access', sub: '공유 범위', icon: Blocks },
]

export function AppShell() {
  const { performanceMode, setPerformanceMode, workspace, toast } = useMemory()
  return (
    <div className={`${styles.shell} ${performanceMode ? styles.performance : ''}`}>
      <aside className={styles.sidebar}>
        <div className={styles.brand}>
          <span className={styles.brandMark}><CircleUserRound size={18} strokeWidth={1.5} /></span>
          <span>Memory OS</span>
        </div>
        <div className={styles.status}><span className={styles.liveDot} /> MEMORY ONLINE <b>{workspace.memoryCount}</b></div>
        <nav className={styles.nav} aria-label="주요 화면">
          {nav.map(({ to, label, sub, icon: Icon, badge }) => (
            <NavLink key={to} to={to} className={({ isActive }) => `${styles.navItem} ${isActive ? styles.active : ''}`}>
              <Icon size={17} strokeWidth={1.45} aria-hidden="true" />
              <span><strong>{label}</strong><small>{sub}</small></span>
              {badge && <em>{badge}</em>}
            </NavLink>
          ))}
        </nav>
        <div className={styles.sidebarBottom}>
          <button className={styles.modeButton} aria-pressed={performanceMode} onClick={() => setPerformanceMode(!performanceMode)}>
            <Gauge size={16} strokeWidth={1.5} />
            <span><strong>Performance</strong><small>{performanceMode ? '효과 줄임' : 'Full visual'}</small></span>
          </button>
          <NavLink to="/settings" className={({ isActive }) => `${styles.navItem} ${isActive ? styles.active : ''}`}>
            <Settings2 size={17} strokeWidth={1.45} />
            <span><strong>Settings</strong><small>원본 기억</small></span>
          </NavLink>
          <div className={styles.profile}><span>IH</span><div><strong>[USER]</strong><small>마지막 동기화 · 방금</small></div><Database size={14} /></div>
        </div>
      </aside>
      <main className={styles.main}><Outlet /></main>
      {toast && <div className={styles.toast} role="status">{toast}</div>}
    </div>
  )
}

---APPSHELL CSS---
.shell { display: grid; grid-template-columns: 224px minmax(0, 1fr); width: 100vw; height: 100vh; background: var(--bg); }
.sidebar { display: flex; flex-direction: column; min-height: 0; padding: 24px 14px 16px; border-right: 1px solid var(--line); background: #0a0b0d; }
.brand { display: flex; align-items: center; gap: 10px; padding: 0 10px; font: 500 15px/1 'Space Grotesk'; letter-spacing: -.02em; }
.brandMark { display: grid; place-items: center; width: 28px; height: 28px; border: 1px solid var(--line-strong); border-radius: 50%; }
.status { display: flex; align-items: center; gap: 7px; margin: 25px 10px 17px; color: var(--text-dim); font: 500 8px/1 'Space Grotesk'; letter-spacing: .14em; }
.status b { margin-left: auto; color: var(--text-soft); font-size: 9px; }
.liveDot { width: 5px; height: 5px; border-radius: 50%; background: var(--paper); box-shadow: 0 0 10px var(--paper); }
.nav { display: flex; flex-direction: column; gap: 3px; }
.navItem, .modeButton { position: relative; display: flex; align-items: center; gap: 11px; width: 100%; min-height: 48px; padding: 8px 10px; border: 0; border-radius: 9px; color: var(--text-dim); background: transparent; text-decoration: none; cursor: pointer; transition: background 180ms var(--ease), color 180ms var(--ease); }
.navItem:hover, .modeButton:hover { color: var(--text-soft); background: rgba(242,239,228,.04); }
.navItem.active { color: var(--text); background: rgba(242,239,228,.075); }
.navItem.active::before { position: absolute; left: -14px; width: 2px; height: 22px; border-radius: 2px; background: var(--paper); content: ''; }
.navItem span, .modeButton span { display: flex; flex: 1; flex-direction: column; gap: 4px; text-align: left; }
.navItem strong, .modeButton strong { font: 500 12px/1 'Space Grotesk'; letter-spacing: .01em; }
.navItem small, .modeButton small { color: var(--text-dim); font: 300 9px/1 'Noto Sans KR'; }
.navItem em { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; color: var(--ink); background: var(--paper); font: 600 9px/1 'Space Grotesk'; font-style: normal; }
.sidebarBottom { display: flex; flex-direction: column; gap: 3px; margin-top: auto; }
.modeButton { border-top: 1px solid var(--line); border-radius: 0; }
.profile { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 13px 10px 4px; border-top: 1px solid var(--line); color: var(--text-dim); }
.profile > span { display: grid; place-items: center; width: 28px; height: 28px; flex: none; border-radius: 50%; color: var(--ink); background: var(--paper); font: 600 9px/1 'Space Grotesk'; }
.profile div { display: flex; min-width: 0; flex: 1; flex-direction: column; gap: 4px; }
.profile strong { color: var(--text-soft); font: 500 10px/1 'Space Grotesk'; }
.profile small { overflow: hidden; font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.main { min-width: 0; min-height: 0; overflow: hidden; }
.toast { position: fixed; z-index: 100; right: 28px; bottom: 24px; padding: 11px 15px; border: 1px solid var(--line-strong); border-radius: 10px; color: var(--ink); background: var(--paper); box-shadow: 0 18px 45px rgba(0,0,0,.38); font-size: 10px; animation: toastIn 220ms var(--ease); }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px); } }
.performance :global(.visual-extra) { display: none !important; }
.performance :global(.visual-blur) { filter: none !important; }

---INDEX APP CSS---
.counter {
  font-size: 16px;
  padding: 5px 10px;
  border-radius: 5px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 2px solid transparent;
  transition: border-color 0.3s;
  margin-bottom: 24px;

  &:hover {
    border-color: var(--accent-border);
  }
  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.hero {
  position: relative;

  .base,
  .framework,
  .vite {
    inset-inline: 0;
    margin: 0 auto;
  }

  .base {
    width: 170px;
    position: relative;
    z-index: 0;
  }

  .framework,
  .vite {
    position: absolute;
  }

  .framework {
    z-index: 1;
    top: 34px;
    height: 28px;
    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)
      scale(1.4);
  }

  .vite {
    z-index: 0;
    top: 107px;
    height: 26px;
    width: auto;
    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)
      scale(0.8);
  }
}

#center {
  display: flex;
  flex-direction: column;
  gap: 25px;
  place-content: center;
  place-items: center;
  flex-grow: 1;

  @media (max-width: 1024px) {
    padding: 32px 20px 24px;
    gap: 18px;
  }
}

#next-steps {
  display: flex;
  border-top: 1px solid var(--border);
  text-align: left;

  & > div {
    flex: 1 1 0;
    padding: 32px;
    @media (max-width: 1024px) {
      padding: 24px 20px;
    }
  }

  .icon {
    margin-bottom: 16px;
    width: 22px;
    height: 22px;
  }

  @media (max-width: 1024px) {
    flex-direction: column;
    text-align: center;
  }
}

#docs {
  border-right: 1px solid var(--border);

  @media (max-width: 1024px) {
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
}

#next-steps ul {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 8px;
  margin: 32px 0 0;

  .logo {
    height: 18px;
  }

  a {
    color: var(--text-h);
    font-size: 16px;
    border-radius: 6px;
    background: var(--social-bg);
    display: flex;
    padding: 6px 12px;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    transition: box-shadow 0.3s;

    &:hover {
      box-shadow: var(--shadow);
    }
    .button-icon {
      height: 18px;
      width: 18px;
    }
  }

  @media (max-width: 1024px) {
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;

    li {
      flex: 1 1 calc(50% - 8px);
    }

    a {
      width: 100%;
      justify-content: center;
      box-sizing: border-box;
    }
  }
}

#spacer {
  height: 88px;
  border-top: 1px solid var(--border);
  @media (max-width: 1024px) {
    height: 48px;
  }
}

.ticks {
  position: relative;
  width: 100%;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: -4.5px;
    border: 5px solid transparent;
  }

  &::before {
    left: 0;
    border-left-color: var(--border);
  }
  &::after {
    right: 0;
    border-right-color: var(--border);
  }
}

:root {
  --bg: #08090b;
  --surface-0: #0b0c0f;
  --surface-1: #101216;
  --surface-2: #15181d;
  --surface-3: #1b1e24;
  --line: rgba(242, 239, 228, 0.1);
  --line-strong: rgba(242, 239, 228, 0.2);
  --text: #f2efe4;
  --text-soft: rgba(242, 239, 228, 0.68);
  --text-dim: rgba(242, 239, 228, 0.4);
  --paper: #f2efe4;
  --ink: #0b0c0f;
  --glass-surface: rgba(18, 20, 26, 0.58);
  --glass-surface-strong: rgba(24, 27, 34, 0.72);
  --glass-border: rgba(255, 255, 255, 0.14);
  --glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  --glass-shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
  --ease: cubic-bezier(0.23, 1, 0.32, 1);
  color: var(--text);
  background: var(--bg);
  font-family: 'Noto Sans KR', system-ui, sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }
html, body, #root { width: 100%; min-width: 1180px; min-height: 100%; margin: 0; }
body { min-height: 100vh; overflow: hidden; background: var(--bg); }
button, input { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--paper); outline-offset: 3px; }
button { color: inherit; }
::selection { background: var(--paper); color: var(--ink); }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; }
}

